import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,_ as u,b as d,k as f,l as p,n as m,o as h,t as g}from"./shared-C5BCElVa.js";import{t as _}from"./git-branch--KUP4I0u.js";import{t as v}from"./save-DdnPoDf-.js";var y=e();function b({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:`Занятие 54.2`,title:`PATCH и сохранённый ответ`,intro:`Проведём частичное изменение через HTTP и проследим его до сохранённой задачи.`,tags:[{icon:(0,y.jsx)(_,{size:15}),label:`Маршрут FastAPI`},{icon:(0,y.jsx)(v,{size:15}),label:`Проверка состояния`}],variant:`project`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`В 54 и 54.1 готовы patch_task и TaskPatch. HTTP-маршрута PATCH пока нет.`},{title:`Новый вопрос`,description:`Как соединить готовую схему и сервис одним HTTP-маршрутом?`},{title:`Результат`,description:`Добавим PATCH, вернём TaskRead и проверим сохранение новым чтением.`}]}),(0,y.jsx)(o,{children:`В 54 подготовили сервис, а в 54.1 разобрали входную схему. Теперь соединим их одним HTTP-маршрутом. PATCH изменит выбранные поля через готовый Planner и вернёт TaskRead. В следующем занятии добавим DELETE.`}),(0,y.jsxs)(s,{number:`01`,title:`Частичное изменение начинается с формы запроса`,children:[(0,y.jsx)(`p`,{children:`При PUT клиент передаёт всю форму задачи. При PATCH он передаёт только поля для изменения. Например, чтобы открыть завершённую задачу, достаточно отправить is_done со значением false. Повторять title и priority не нужно.`}),(0,y.jsxs)(`p`,{children:[`Сначала разделим вход запроса на две части. Путь `,(0,y.jsx)(`code`,{children:`/tasks/{task_id}`}),` выбирает задачу, а JSON-тело передаёт изменения. Положительный ID может быть правильным по формату, но самой задачи может не быть. Формат проверит FastAPI, а существование ID проверит сервис.`]}),(0,y.jsx)(`p`,{children:`Фигурные скобки в пути обозначают место для значения. Например, запрос к /tasks/7 передаст маршруту task_id со значением 7. Этот ID выбирает уже существующую задачу, а не задаёт новое значение поля в теле. Так path и body отвечают на разные вопросы: «какую задачу?» и «что в ней изменить?».`}),(0,y.jsx)(t,{rows:[[`поле пропущено`,`оставляем прежнее значение`],[`поле равно null`,`не задаём новое значение`],[`поле равно False`,`передаём явное значение`],[`поле содержит значение`,`передаём его сервису`]]}),(0,y.jsx)(`p`,{children:`TaskPatch уже перечисляет разрешённые поля и проверяет их. FastAPI создаёт payload из JSON до запуска маршрута. Поэтому маршрут не читает тело вручную и не повторяет проверку. Он берёт task_id из пути, а готовые к проверке значения из payload.`}),(0,y.jsx)(`p`,{children:`В TaskPatch разрешены title, priority и is_done. Поля id и tags клиент не задаёт: ID берётся из адреса, а tags остаются частью полной записи. Это сохраняет границу между разрешёнными изменениями и данными, которыми управляет Planner.`}),(0,y.jsx)(`p`,{children:`Так у каждого входа своя роль: путь выбирает задачу, тело задаёт изменения. Если тип ID, ограничение пути или поля тела неверны, FastAPI вернёт 422 до вызова сервиса.`}),(0,y.jsx)(d,{question:`Клиент отправил {"is_done": false}. Что попадёт в changes?`,options:[`is_done: false`,`пустой словарь`,`все поля со значением null`],correctIndex:0,explanation:`False передано явно, поэтому оно остаётся в changes.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Сохраняем разницу между пропуском и False`,children:[(0,y.jsx)(`p`,{children:`В 54.1 мы увидели: у поля есть значение и признак, передал ли его клиент. Обычный model_dump() может добавить значения по умолчанию и скрыть эту разницу. Здесь используем model_dump(exclude_unset=True, exclude_none=True). Первый флаг убирает пропущенные поля, второй убирает поля со значением null.`}),(0,y.jsx)(`p`,{children:`False не означает «поле не прислали». Это команда снять отметку выполнения. Проверка if value потеряет такое значение, поэтому мы фильтруем присутствие поля и null отдельно. Для другой схемы могут действовать свои правила типов, но в TaskPatch значение False допустимо.`}),(0,y.jsxs)(`p`,{children:[`Это правило знакомо и за пределами Planner. Например, в настройке уведомлений`,` `,(0,y.jsx)(`code`,{children:`{"enabled": false}`}),` означает «выключить». Значение остаётся в словаре. Точно так же `,(0,y.jsx)(`code`,{children:`{"is_done": false}`}),` открывает задачу.`]}),(0,y.jsxs)(`p`,{children:[`Пустой объект `,(0,y.jsx)(`code`,{children:`{}`}),` и поле title со значением null дают пустой словарь. Для существующей задачи это no-op: состояние не меняется. При этом тело обязательно. Отсутствующее тело и весь JSON null нарушают контракт и дают 422, а не превращаются в `,`.`]}),(0,y.jsx)(t,{rows:[[`{"is_done": false}`,`changes содержит is_done: false`],[`{"title": null}`,`changes пустой`],[`{}`,`changes пустой`],[`нет body или весь JSON null`,`FastAPI возвращает 422`]]}),(0,y.jsx)(`p`,{children:`Таблица показывает, что фильтр работает с каждым полем отдельно. Он удаляет пропуск и null, но сохраняет явно переданное значение. Пустой словарь не отменяет поиск задачи: маршрут всё равно передаст ID сервису. Поэтому no-op возможен только для существующей Task.`}),(0,y.jsx)(u,{code:`payload = TaskPatch(is_done=False)
changes = payload.model_dump(
    exclude_unset=True,
    exclude_none=True,
)
print(changes)`,output:`{'is_done': False}`,hint:`Пропущенные поля и None удаляются. Явное False остаётся.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Маршрут соединяет проверку, сервис и ответ`,children:[(0,y.jsx)(`p`,{children:`API отвечает за HTTP-границу: разбирает запрос и выбирает ответ. PlannerService меняет задачу и сохраняет её через общее хранилище. Поэтому handler не ищет запись в JSON, не создаёт Task вручную и не вызывает save.`}),(0,y.jsx)(g,{caption:`Путь PATCH от HTTP-запроса до публичного ответа`,orientation:`vertical`,children:(0,y.jsxs)(h,{label:`Обработка PATCH запроса`,orientation:`vertical`,children:[(0,y.jsx)(p,{title:`HTTP-запрос`,children:(0,y.jsx)(`p`,{children:`task_id и JSON тела`})}),(0,y.jsx)(m,{label:`FastAPI проверяет путь и body`,direction:`forward`}),(0,y.jsx)(p,{title:`Словарь changes`,children:(0,y.jsx)(`p`,{children:`только присланные значения`})}),(0,y.jsx)(m,{label:`PlannerService.patch_task`,direction:`forward`}),(0,y.jsx)(p,{title:`Сохранённая Task`,shape:`database`,children:(0,y.jsx)(`p`,{children:`полная доменная запись`})}),(0,y.jsx)(m,{label:`TaskRead формирует публичный ответ`,direction:`forward`,lineStyle:`dashed`}),(0,y.jsx)(p,{title:`HTTP-ответ`,children:(0,y.jsx)(`p`,{children:`id, title, priority, is_done`})})]})}),(0,y.jsx)(`p`,{children:`Соберём маршрут по шагам. FastAPI проверяет положительный task_id и обязательное тело TaskPatch. Request даёт доступ к текущему Planner через request.app.state. Затем маршрут получает changes с двумя знакомыми флагами и передаёт их существующему patch_task. Помощник _call_with_task_not_found_as_404 переводит только TaskNotFoundError в 404. Наконец, _task_read_data готовит результат для response_model=TaskRead.`}),(0,y.jsxs)(`p`,{children:[`Распаковка `,(0,y.jsx)(`code`,{children:`**changes`}),` передаёт ключи словаря как именованные аргументы. Например, словарь`,` `,(0,y.jsx)(`code`,{children:`{"is_done": false}`}),` превращается в вызов patch_task(task_id, is_done=False). Пустой словарь не передаёт полей для изменения, но сервис всё равно получает ID и ищет задачу. Затем сервис меняет запись и сохраняет её через общее хранилище.`]}),(0,y.jsx)(`p`,{children:`Request нужен, чтобы получить Planner текущего приложения, а не отдельный глобальный объект. CLI читает то же настроенное JSON-хранилище. Если маршрут сам изменит файл или возьмёт другой путь к нему, новое чтение может показать другое состояние.`}),(0,y.jsx)(`p`,{children:`Ответ TaskRead содержит id, title, priority и is_done. tags остаются в полной записи, но не входят в публичный ответ. За сохранение tags и других полей отвечает прежний сервис.`}),(0,y.jsx)(r,{tone:`info`,children:`Успешный маршрут возвращает 200 и обновлённую TaskRead.`}),(0,y.jsx)(d,{question:`Какой слой должен непосредственно вызвать PlannerService.patch_task?`,options:[`HTTP-маршрут`,`JSON-файл`,`клиентский интерфейс`],correctIndex:0,explanation:`Маршрут передаёт проверенные изменения сервису. Сервис обновляет задачу и сохраняет её.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Ошибка зависит от того, на каком шаге остановился запрос`,children:[(0,y.jsx)(n,{code:`try:
    task = request.app.state.planner.patch_task(task_id, **changes)
except Exception as error:
    raise HTTPException(status_code=404, detail="Task not found") from error`,question:`Что произойдёт, если patch_task завершится с StorageError?`,options:[`404: широкий except скроет ошибку хранения`,`422: FastAPI отклонит уже проверенное тело`,`200: маршрут вернёт пустой ответ`],correctIndex:0,explanation:`except Exception поймает и TaskNotFoundError, и StorageError. Помощник переводит в 404 только отсутствие задачи.`,fix:`task = _call_with_task_not_found_as_404(
    request.app.state.planner.patch_task, task_id, **changes
)`}),(0,y.jsx)(`p`,{children:`FastAPI проверяет путь и тело до запуска handler. Например, ID строкой, 0 или -1 не подходит положительному Path и даёт 422. Положительный целый ID проходит эту проверку, но задачи может не быть. Тогда сервис сообщает TaskNotFoundError, а помощник возвращает 404.`}),(0,y.jsx)(`p`,{children:`Например, TaskPatch отклонит пустой title. Отсутствующее тело и весь JSON null тоже дают 422 до вызова сервиса. Если чтение или запись JSON завершится StorageError, это ошибка хранилища, а не 404. Широкий except Exception скрыл бы её. Поэтому helper ловит только известное исключение TaskNotFoundError.`}),(0,y.jsx)(t,{rows:[[`200`,`задача найдена, ответ содержит TaskRead`],[`422`,`неверный path или body, сервис не вызван`],[`404`,`ID допустимый, но задача не найдена`],[`StorageError`,`сбой хранилища остаётся отдельной ошибкой`]]}),(0,y.jsx)(`p`,{children:`После отказа перечитайте задачу и сравните её с исходным снимком. При 422 handler ещё не запускался. При 404 сервис не нашёл задачу с этим ID. Оба результата отличаются от сбоя хранилища, где операция не завершилась штатно и причину нельзя скрывать под другим статусом.`}),(0,y.jsxs)(`p`,{children:[`Для проверки 404 не угадываем ID. Сначала отправляем GET`,` `,(0,y.jsx)(`code`,{children:`/tasks/{candidate_id}`}),`. Если ответ 200, выбираем другой положительный ID. Если ответ 404, этим же ID проверяем PATCH с полем и PATCH с `,(0,y.jsx)(`code`,{children:`{}`}),`. Оба запроса должны вернуть 404, потому что сервис всё равно ищет задачу. Так мы проверяем и пустые изменения, и отсутствие ресурса.`]}),(0,y.jsx)(c,{statement:`Для отсутствующего ID пустой PATCH {} вернёт 200, потому что менять нечего.`,isTrue:!1,explanation:`Сервис получает ID и ищет задачу. Пустой PATCH для существующей задачи ничего не меняет, а для отсутствующей вернёт 404.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Ответ и сохранённая задача показывают разные стороны результата`,children:[(0,y.jsx)(`p`,{children:`TaskPatch принимает title, priority и is_done. Она не принимает id и tags, поэтому эти поля нельзя изменить этим маршрутом. TaskRead задаёт публичный ответ: id, title, priority и is_done. Полная Task также хранит tags, но схема ответа их не показывает. Отсутствие tags в ответе не означает, что они удалены из JSON.`}),(0,y.jsx)(`p`,{children:`Перед PATCH сохраним исходный снимок. GET /tasks показывает задачи и их публичные поля, а GET /stats показывает total, open и done. Найдите тот же ID в привычном CLI: там можно проверить полную запись и tags. API и CLI должны читать одно настроенное хранилище.`}),(0,y.jsx)(`p`,{children:`Для проверки False нужна завершённая задача. Если такой нет, выберите существующую и отметьте её готовым PUT: задайте is_done=true и сохраните прежние title и priority. PUT требует полную форму, поэтому эти значения нельзя пропускать. Если список пуст, создайте одну задачу готовым POST, возьмите ID из ответа и завершите её готовым PUT. После подготовки снова прочитайте задачу, статистику и CLI. Этот снимок будет исходной точкой.`}),(0,y.jsx)(`p`,{children:`Снимок делают после подготовки, потому что PUT или POST уже меняют данные и счётчики. Запишите фактический ID и сверяйте именно эту задачу после PATCH. Запись соседа нужна, чтобы заметить случайное изменение другой задачи. Для каждого сравнения используйте тот же JSON, к которому подключено приложение.`}),(0,y.jsx)(l,{question:`Какой вариант надёжнее подтверждает, что PATCH сохранил изменение?`,left:{title:`Сверить только ответ PATCH`,code:`PATCH /tasks/{task_id}
# ответ содержит is_done: false`,note:`Проверяет контракт ответа, но не делает отдельного чтения.`},right:{title:`Проверить ответ и перечитать задачу`,code:`PATCH /tasks/{task_id}
GET /tasks/{task_id}
# сверить фактические поля`,note:`Проверяет HTTP-ответ и состояние после завершения запроса.`},preferred:`right`,explanation:`Ответ подтверждает публичную форму. Новый GET или CLI подтверждает сохранённое состояние.`}),(0,y.jsx)(`p`,{children:`После PATCH проверьте статус 200 и четыре поля ответа. Затем перечитайте ту же задачу через GET и CLI. Сравните is_done, прежние title и priority, tags и данные соседа с исходным снимком. Новое чтение подтверждает сохранение после завершения запроса.`}),(0,y.jsx)(`p`,{children:`После неверных запросов сравните данные с ожидаемым состоянием после успешного PATCH: is_done остаётся false, остальные поля задачи и счётчики не меняются. Данные соседа должны совпасть с исходным снимком. Так мы проверяем, что ошибки не затронули хранилище.`}),(0,y.jsxs)(`p`,{children:[`Если меняется is_done с true на false, total остаётся прежним, open растёт на 1, а done уменьшается на 1. Для `,` и null-поля значения задачи и счётчики остаются прежними. Один только total не доказывает результат: при смене статуса он не меняется. Сверяйте конкретную задачу, все три счётчика и данные соседа.`]})]}),(0,y.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(f,{variant:`connected`,items:[{title:`Исходный снимок готов`,description:`Сверим GET, статистику и CLI до изменений.`},{title:`Маршрут PATCH добавлен`,description:`Передадим TaskPatch прежнему сервису и вернём TaskRead.`},{title:`Границы проверены`,description:`Сравним False, no-op, 422 и 404 на реальном API.`},{title:`Сохранение подтверждено`,description:`Перечитаем ту же задачу через GET и CLI.`}]}),(0,y.jsx)(`p`,{children:`Сначала сохраним исходные поля, tags, статистику и данные соседа. Затем добавим один маршрут PATCH. Проверим is_done=false, пустой объект и null в поле. Эти запросы покажут разницу между изменением и no-op.`}),(0,y.jsx)(`p`,{children:`Отдельно проверим неверный ввод и отсутствующий ID. В конце перечитаем ту же задачу через GET и CLI, затем сравним её с исходным снимком. Так практика проверит и HTTP-ответ, и сохранённые данные. Следующее занятие добавит DELETE, его здесь не реализуем.`})]})]})}export{b as Lesson54_2};